
(function(){
 const EMBEDDED={libro_servicio_verano:{name:"LIBRO_SERVICIO_VERANO_22-6-2026.pdf",data:""},libro_servicio_invierno:{name:"LIBRO_SERVICIO_INVIERNO_2026_2027.pdf",data:""},
  gastos_sociales:{name:"GASTOS_SOCIALES_REGISTRO_INTERNO.pdf",data:""},
  recorridos_paradas:{name:"RECORRIDOS_Y_PARADAS_BOLSA_EMPLEO_2024.pdf",data:""},
  reglamento:{name:"REGLAMENTO_TECNICO_PRESTACION_SERVICIO.pdf",data:""},
  licencias:{name:"LICENCIAS.pdf",data:""},
  convenio:{name:"CONVENIO_2023_2026.pdf",data:""}
 };
 function openEmbedded(key){
   const d=EMBEDDED[key]; if(!d)return false;
   const bin=atob(d.data), bytes=new Uint8Array(bin.length);
   for(let i=0;i<bin.length;i++) bytes[i]=bin.charCodeAt(i);
   const url=URL.createObjectURL(new Blob([bytes],{type:"application/pdf"}));
   const w=window.open(url,"_blank");
   if(!w) location.href=url;
   setTimeout(()=>URL.revokeObjectURL(url),300000);
   return true;
 }
 document.addEventListener("click",function(e){
   const b=e.target.closest("[data-doc-open]");
   if(!b)return;
   let key=b.dataset.docOpen;
   if(key==="verano") key="libro_servicio_verano";
   if(key==="invierno") key="libro_servicio_invierno";
   if(EMBEDDED[key]){
     e.preventDefault(); e.stopImmediatePropagation();
     openEmbedded(key);
   }
 },true);
})();
